"""Makes the PNG fixtures of tests/suite/blitz3d_texture_formats_pixels.bb.

gradient16.png is a gray ramp of 16 bits per channel that rises by 100 per texel (a bit more than a third of a step of 8 bits),
gradient8.png is the same ramp rounded to 8 bits, and mask16.png is 16 bit with a black texel and a texel that is almost black.

Usage: generate_highbit_fixtures.py <output folder>
"""
import struct
import sys
import zlib
from pathlib import Path


def png(path, width, height, depth, rows):
    def chunk(kind, data):
        body = kind + data
        return struct.pack(">I", len(data)) + body + struct.pack(">I", zlib.crc32(body))

    raw = b"".join(b"\0" + row for row in rows)
    data = b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", width, height, depth, 2, 0, 0, 0))
    data += chunk(b"IDAT", zlib.compress(raw)) + chunk(b"IEND", b"")
    Path(path).write_bytes(data)


def main():
    out = Path(sys.argv[1])
    out.mkdir(parents=True, exist_ok=True)
    width, height = 64, 4
    ramp = [x * 100 for x in range(width)]
    png(out / "gradient16.png", width, height, 16, [b"".join(struct.pack(">HHH", v, v, v) for v in ramp)] * height)
    png(out / "gradient8.png", width, height, 8, [b"".join(bytes([round(v / 257)] * 3) for v in ramp)] * height)
    mask = [(0, 0, 0), (60000, 40000, 20000), (200, 100, 0), (65535, 65535, 65535)]
    png(out / "mask16.png", 4, 1, 16, [b"".join(struct.pack(">HHH", *p) for p in mask)])


main()
